const sha=x=>createHash('sha256').update(typeof x==='string'?x:JSON.stringify(x)).digest('hex');
const server=await createServer({root,configFile:false,appType:'custom',logLevel:'silent',server:{middlewareMode:true,hmr:false,watch:null},optimizeDeps:{noDiscovery:true,include:[]},plugins:[{name:'isolated-worker-wasm',enforce:'pre',async load(id){if(id.endsWith('tiktoken_bg.wasm'))return `export default new WebAssembly.Module(Uint8Array.from(${JSON.stringify([...await readFile(id)])}));`;}}]});
try {
 const core=Object.assign({},...await Promise.all(['/src/lib/habitat/society/index.ts','/src/lib/habitat/society/instructions.ts','/src/lib/habitat/engine/state.ts','/src/lib/habitat/residents.ts','/workers/habitat-runtime/src/society-scheduler.ts','/workers/habitat-runtime/src/providers/groq-tokenizer.ts','/workers/habitat-runtime/src/providers/groq-token-estimate.ts','/workers/habitat-runtime/src/providers/workers-ai.ts','/workers/habitat-runtime/src/providers/shared.ts'].map(p=>server.ssrLoadModule(p))));
 const world=core.genesisState(91),state=core.createSocietyState(world,1000),jobs=[];
 for(const{id:actor} of core.RESIDENTS){const input={world,state,actor,nowMs:2000,sequence:0,generation:0,worldRevision:0,habitatId:'offline-p5-study'};const p4=core.prepareSocietyJob({...input,protocolVersion:4}).job,p5=core.prepareSocietyJob(input).job;assert.equal(p4.prompt.user,p5.prompt.user);jobs.push({group:'initial',actor,p4,p5});}
 const path='docs/research/model-society-final-dialogue-local-2026-09-08/ledger.json',text=await readFile(root+'/'+path,'utf8'),ledger=JSON.parse(text);
 for(const row of ledger.entries.filter(e=>e.kind==='cognition')){const p4=row.job.job;const schema=core.orderedChoiceJsonSchemaFromProposal(p4.outputContract.jsonSchema),p5={...p4,prompt:{...p4.prompt,system:core.orderedSystemFromProposalSystem(p4.prompt.system)},outputContract:{...p4.outputContract,version:5,schemaHash:'sha256:'+sha(schema),jsonSchema:schema}};jobs.push({group:'final-dialogue',actor:row.job.actor,sequence:row.job.turn?.sequence??row.job.sequence,p4,p5,original:row.receipt.output});}
 const rows=[],samples=[];
 async function measure(job){const parts=[job.prompt.system,job.prompt.user,JSON.stringify(job.outputContract.jsonSchema)],tokens=await core.tokenizeGroqOrdinary(parts);assert.ok(tokens);const cfPayload=JSON.stringify(core.workersAIInput(job,'@cf/openai/gpt-oss-120b'));return{ordinaryTokens:Object.fromEntries(['system','user','schema'].map((k,i)=>[k,tokens[i].length])),groqMaximum:tokens.reduce((n,a)=>n+a.length,128+job.maxOutputTokens),outputMaximum:job.maxOutputTokens,framingMargin:128,utf8Bytes:Object.fromEntries(['system','user','schema'].map((k,i)=>[k,Buffer.byteLength(parts[i])])),cfPayloadBytes:Buffer.byteLength(cfPayload),cfNeuronMaximum:core.estimateWorkersAINeurons('@cf/openai/gpt-oss-120b',core.estimateTokens(cfPayload),job.maxOutputTokens),jobHash:sha(job)};}
 for(const f of jobs){rows.push({group:f.group,actor:f.actor,sequence:f.sequence,p4:await measure(f.p4),p5:await measure(f.p5)});if(!f.original)continue;
  const original=f.original,s4=f.p4.outputContract.jsonSchema,s5=f.p5.outputContract.jsonSchema;
  const ids=s4.$defs.choice_deal.anyOf.find(v=>v.properties.offerId).properties.offerId.enum;
  const raw=[original,{message:original.message},...ids.flatMap(offerId=>['accept','reject'].map(kind=>({message:{to:original.message.to,text:'A synthetic response.'},deal:{kind,offerId}})))];
  const valid=raw.map(value=>{assert.ok(z.fromJSONSchema(s4).safeParse(value).success);const a=core.toOrderedChoice(value);assert.ok(a.ok);assert.ok(z.fromJSONSchema(s5).safeParse(a.value).success);assert.deepEqual(core.fromOrderedChoice(a.value),{ok:true,value});return a.value;});
  const invalid=[{turn:[valid[0].turn[1],valid[0].turn[0]]},{turn:[valid[0].turn[0]]},{turn:[...valid[0].turn,{}]},{turn:[{choice:'accept:offer:missing'},valid[0].turn[1]]},{turn:[valid[0].turn[0],{...valid[0].turn[1],message:{...valid[0].turn[1].message,close:true}}]}];for(const bad of invalid)assert.equal(z.fromJSONSchema(s5).safeParse(bad).success,false);samples.push({actor:f.actor,schema:s5,valid,invalid});
 }
 const result={scope:'Implemented P5 offline components, not provider inference. Initial pair uses current producer; final-dialogue pair retains exact saved P4 USER and derives only P5 format instructions/schema.',requests,sourceLedger:{path,sha256:sha(text)},rows};
 await writeFile('/tmp/villa-p5-final-grammar-samples.json',JSON.stringify({samples}));await writeFile('/tmp/villa-p5-final-measurement.json',JSON.stringify(result,null,2));
 console.log(JSON.stringify({requests,initialMax:{p4:Math.max(...rows.slice(0,25).map(r=>r.p4.groqMaximum)),p5:Math.max(...rows.slice(0,25).map(r=>r.p5.groqMaximum))},final:rows.slice(25)}));
}finally{await server.close();}

import assert from 'node:assert/strict';
