try {
 const core=Object.assign({},...await Promise.all(['/src/lib/habitat/society/index.ts','/workers/habitat-runtime/src/domain.ts','/workers/habitat-runtime/src/society-scheduler.ts','/workers/habitat-runtime/src/providers/router.ts','/workers/habitat-runtime/src/providers/groq-token-estimate.ts','/workers/habitat-runtime/src/providers/groq-tokenizer.ts','/workers/habitat-runtime/src/quota.ts','/workers/habitat-runtime/src/providers/workers-ai.ts','/workers/habitat-runtime/src/providers/shared.ts'].map(p=>server.ssrLoadModule(p))));
 assert.ok(await core.tokenizeGroqOrdinary(['Testing ordinary token count.']),'Must use actual tokenizer, not its byte fallback');
 const at=Date.parse('2026-09-08T12:00:00Z');let clock=at-300000,sequence=0;
 let world=core.createGenesisWorld(),society=core.createSocietyState(world,clock-1000);
 function apply(actor,response){
  clock+=1000;const turn=core.prepareSocietyTurn(society,world,actor,{nowMs:clock,sequence:++sequence,generation:0});
  const raw={message:response.message};
  if(!society.minds[actor].project)raw.project={mode:'replace',goal:'Keep a synthetic loan register.',why:'This is an isolated scheduling test.',visibility:'private',steps:[]};
  if(response.offer)raw.deal={kind:'loan',direction:'lend',cells:response.offer.terms.cells,dueInDays:1};
  if(response.respond)raw.deal={kind:'accept',offerId:response.respond.offerId};
  const r=core.applyProposalCapabilityChoice(society,world,turn,raw,{nowMs:clock,generation:0});
  assert.equal(r.ok,true,r.code);society=r.state;world=r.world;
 }
 const loans=Number(process.argv[2]??24);
 for(const target of Object.keys(society.minds).slice(1,loans+1)){
  apply('A',{message:{to:target,text:'Synthetic loan offer.',close:false},offer:{terms:{kind:'loan',from:'A',to:target,cells:0.1,dueDay:101},expiresInWatches:2}});
  apply(target,{message:{to:'A',text:'I accept this synthetic loan.',close:false},respond:{offerId:society.offers.at(-1).id,decision:'accept'}});
  apply('A',{message:{to:target,text:'This synthetic exchange is closed.',close:true}});
 }
 // Keep unserved identities out of bootstrap for smaller boundary searches.
 for(const m of Object.values(society.minds))if(m.lastSuccessAtMs===null){m.lastSuccessAtMs=clock;m.lastAttemptAtMs=clock;}
 apply('B',{message:{to:'A',text:'Please review these existing obligations.',close:false}});
 apply('C',{message:{to:'D',text:'Can we discuss the shared stores?',close:false}});
 const now=clock+1000;sequence++;if(sequence%2===0)sequence++;
 assert.equal(core.parseSocietyState(society).ok,true);core.deserializeWorldState(core.serializeWorldState(world));
 const chosen=core.nextSocietyActor(society,now,sequence);
 const a=core.prepareSocietyJob({state:society,world,actor:'A',nowMs:now,sequence,generation:0,worldRevision:1,habitatId:'synthetic-hol',protocolVersion:Number(process.argv[3]??5)});
 const d=core.prepareSocietyJob({state:society,world,actor:'D',nowMs:now,sequence,generation:0,worldRevision:1,habitatId:'synthetic-hol',protocolVersion:Number(process.argv[3]??5)});
 const tokenA=await core.estimateGroqInputTokens(a.job)+a.job.maxOutputTokens;
 const tokenD=await core.estimateGroqInputTokens(d.job)+d.job.maxOutputTokens;
 const db=new DatabaseSync(':memory:'),source=await readFile(root+'/workers/habitat-runtime/src/habitat-world.ts','utf8');
 for(const table of ['provider_usage_daily','quota_reservations','provider_breakers','provider_attempts'])db.exec(source.match(new RegExp(`CREATE TABLE IF NOT EXISTS ${table} \\([\\s\\S]+?\\n      \\);`))[0]);
 db.exec('ALTER TABLE quota_reservations ADD COLUMN usage_confirmed INTEGER NOT NULL DEFAULT 0');
 const sql={exec(query,...args){const stmt=db.prepare(query);const rows=stmt.columns().length?stmt.all(...args):(stmt.run(...args),[]);return{toArray:()=>rows,one:()=>{assert.equal(rows.length,1);return rows[0];}};}};
 const config={WORKERS_AI_MODEL:'@cf/openai/gpt-oss-120b',GROQ_MODEL:'openai/gpt-oss-20b',WORKERS_AI_DAILY_NEURONS_LIMIT:8000,GROQ_DAILY_TOTAL_TOKENS_LIMIT:150000};
 const quota=new core.SqlQuotaLedger(sql,config);
 // Prior real metered cost, represented synthetically here: only100CF units remain.
 assert.equal(quota.reserve('synthetic-history:workers-ai:1','workers-ai',{requests:1,inputTokens:1,outputTokens:1,neurons:7900},now-60000).allowed,true);
 quota.markDispatched('synthetic-history:workers-ai:1',now-60000);quota.settle('synthetic-history:workers-ai:1',{inputTokens:1000,outputTokens:100,neurons:7900},now-59000);
 const readyA=await core.cognitionReadyAt({job:a.job,config,quota,nowMs:now,groqAvailable:true});
 const readyD=await core.cognitionReadyAt({job:d.job,config,quota,nowMs:now,groqAvailable:true});
 const components={};
 for(const [id,job] of [['A',a.job],['D',d.job]]) {
  const parts=[job.prompt.system,job.prompt.user,JSON.stringify(job.outputContract.jsonSchema)];
  const tokens=await core.tokenizeGroqOrdinary(parts);assert.ok(tokens,'No tokenizer fallback allowed');
  const cfPayload=JSON.stringify(core.workersAIInput(job,config.WORKERS_AI_MODEL));
  components[id]={groq:{ordinaryTokens:Object.fromEntries(['system','user','schema'].map((key,i)=>[key,tokens[i].length])),framingMargin:core.GROQ_FRAMING_MARGIN,outputMaximum:job.maxOutputTokens},utf8Bytes:Object.fromEntries(['system','user','schema'].map((key,i)=>[key,Buffer.byteLength(parts[i])])),cf:{serializedPayloadBytes:Buffer.byteLength(cfPayload),inputReservation:core.estimateTokens(cfPayload),outputMaximum:job.maxOutputTokens}};
 }
 const maxima=Object.fromEntries([['A',a.job],['D',d.job]].map(([id,job])=>[id,core.estimateWorkersAINeurons(config.WORKERS_AI_MODEL,core.estimateTokens(JSON.stringify(core.workersAIInput(job,config.WORKERS_AI_MODEL))),job.maxOutputTokens)]));
 console.log(JSON.stringify({components,maxima,loans,validSociety:true,validWorld:true,chosen,otherWaiting:society.conversations.filter(c=>c.status==='open').map(c=>c.nextSpeaker),groqTotals:{A:tokenA,D:tokenD},promptBytes:{A:a.turn.promptBytes,D:d.turn.promptBytes},now:new Date(now).toISOString(),readyA:new Date(readyA).toISOString(),readyD:new Date(readyD).toISOString(),delayAminutes:(readyA-now)/60000,delayDminutes:(readyD-now)/60000,fetches}));
 db.close();assert.equal(fetches,0);
}finally{await server.close();}
